public class Shadow {
    static int x = 5;
    int y = 7;
    public static void main(String[] args) {
        int x = 10;
        Shadow s = new Shadow();
        s.change(x);
        System.out.println(x + " " + Shadow.x + " " + s.y);
    }
    void change(int x) {
        x++;
        Shadow.x = x;
        y = this.y + x;
    }
}
